      q: "P1·P2·P3가 각각 무슨 일을 하나요?",
      a:
        "세 병은 재현탁 → 용해 → 중화 순서 자체가 원리입니다.\n" +
        "P1(250 µL)은 Tris 완충액·EDTA·RNase A로 펠렛을 고르게 풀어 줍니다. " +
        "P2(250 µL)의 SDS는 세포막 지질을 녹이고 NaOH는 DNA 이중나선의 수소결합을 끊어 세포를 터뜨립니다. " +
        "P3(350 µL)의 산성 아세트산염은 pH를 되돌려 염색체 DNA와 단백질만 침전시킵니다(3주 실험방법B).\n" +
        "손에서 달라지는 것 — P1은 덩어리가 없어질 때까지 풀고, P2·P3는 뒤집어 섞으며 각각 5분을 지킵니다.",
      tags: ["P1","P2","P3","세 용액","알칼리 용해법","alkaline lysis","재현탁","용해","중화","버퍼","용액 역할","resuspension","lysis","neutralization","순서"]
