        "손에서 달라지는 것 — 그 흰 덩어리가 오늘 버리는 부분입니다. 상등액 500 µL만 옮기고 바닥은 건드리지 않습니다.",
      tags: ["염색체","chromosomal","genomic","흰 덩어리","침전","supercoiled","선형","분리 원리","왜 남는가","핵심 질문","재결합"]
