            keyNumbers: ["supercoiled(초나선) = 가장 빠름", "linear(선형·한 곳 잘림) = 중간", "nicked/open(열린 원형·한 가닥 끊김) = 가장 느림", "한 플라스미드도 여러 밴드로 보일 수 있음"],
